CustomField.formula:
if(Text( CallResolution )="Waiting For Account Creation", "05 Waiting for Account Creation",
if(Text( CallResolution )!="Not Resolved", "99 Resolved",
if(
 Create_Account__c || Create_Case__c || Create_Contact__c || Set_Follow_Up__c || Update_Case__c,
	"01 Flagged to: "&
	if(Create_Account__c, "Create Account"&BR(), "")&
	if(Create_Case__c , "Create Case"&BR(), "")&
	if(Create_Contact__c , "Create Contact"&BR(), "")&
	if(Set_Follow_Up__c , "Create Follow Up"&BR(), "")&
	if(Update_Case__c, "Update Case", "")
,
if(Current_Owner__c = "Voicemail", "03 Resolve Voicemail",
if(Current_Owner__c = "Missed Call", "04 Call Back Missed Call",
"02 Resolve"
)))))
